<section class="hero compact"><div><span class="eyebrow">DETAIL RECORD</span><h1 class="mono"><?=e($letter['letter_number'])?></h1><p>Nomor agenda <?=e($letter['agenda_number'])?> • <?=e($letter['letter_type_name'])?></p></div><span class="badge big <?=strtolower($letter['status'])?>"><?=e($letter['status'])?></span></section>
<div class="detail-grid"><section class="card"><div class="section-title"><div><span class="eyebrow">INFORMASI</span><h2>Data Surat</h2></div></div><dl class="detail-list"><div><dt>Tim kerja</dt><dd><?=e($letter['work_team_name'])?></dd></div><div><dt>Pengaju</dt><dd><?=e($letter['requester_name'])?></dd></div><div><dt>Sistem</dt><dd><?=e($letter['system_type'])?></dd></div><div><dt>Tanggal surat</dt><dd><?=e(format_date_id($letter['letter_date']))?></dd></div><div><dt>Sifat</dt><dd><?=e(sensitivity_label($letter['sensitivity']))?></dd></div><div><dt>Anggaran</dt><dd><?=$letter['uses_budget']==='Y'?'Ya':'Tidak'?></dd></div><div><dt>Jenis arsip</dt><dd><?=e($letter['archive_type'])?></dd></div><div><dt>Klasifikasi</dt><dd><span class="code"><?=e($letter['classification_code'])?></span></dd></div><div class="wide"><dt>Tujuan</dt><dd><?=e($letter['recipient'])?></dd></div><div class="wide"><dt>Perihal</dt><dd><?=e($letter['subject'])?></dd></div><?php if($letter['notes']):?><div class="wide"><dt>Catatan</dt><dd><?=e($letter['notes'])?></dd></div><?php endif;?></dl></section><aside class="card"><span class="eyebrow">AUDIT</span><h2>Status Nomor</h2><?php if($letter['status']==='ACTIVE'):?><p>Nomor aktif dan sudah terpakai. Nomor tidak boleh dihapus dari history.</p><?php if(\App\Core\Auth::isAdmin()):?><form method="post" action="/letters/<?=$letter['id']?>/cancel" class="stack"><?=csrf_field()?><label>Alasan pembatalan<textarea name="reason" rows="4" placeholder="Contoh: Salah jenis surat ..." required></textarea></label><button class="btn danger" type="submit" onclick="return confirm('Nomor akan ditandai dibatalkan dan tidak dapat digunakan ulang. Lanjut?')">Batalkan Nomor</button></form><?php endif;?><?php else:?><div class="cancel-box"><b>DIBATALKAN</b><span><?=e($letter['cancellation_reason'])?></span><small>Oleh <?=e($letter['cancelled_by_name']??'-')?> • <?=e(format_date_id($letter['cancelled_at'],true))?></small></div><?php endif;?></aside></div>
